function buildDistinctGeometry(
  archetype: ParametricArchetype,
  ordinal: number,
  seedId: string
): ParametricGeometryParams {
  const h = detHash(`${seedId}:${ordinal}`);
  const pick = <T,>(arr: readonly T[], salt: number): T =>
    arr[(ordinal + ((h >>> salt) & 0xff)) % arr.length];

  switch (archetype) {
    case "precision-dial-gauge":
      return {
        archetype,
        arcSweepDeg: 180 + ((ordinal * 23 + (h & 31)) % 125),
        majorTicks: 5 + (ordinal % 12),
        minorSubdivisions: 2 + (ordinal % 4),
        dangerZoneStartPct: Number((0.52 + ((ordinal * 7) % 36) * 0.01).toFixed(2)),
        bezelStyle: pick(["double-ring", "octagonal-bolted", "square-panel", "flanged-brass"] as const, 2),
        needleStyle: pick(["tapered", "counterweight", "vernier-dual", "chronograph"] as const, 4),
        subDialCount: pick([0, 1, 2] as const, 6),
        targetNorm: Number((0.34 + ((ordinal * 11) % 62) * 0.01).toFixed(2)),
        secondaryNorm: ordinal % 2 === 0 ? Number((0.22 + ((ordinal * 5) % 55) * 0.01).toFixed(2)) : undefined,
      };
    case "rotary-valve-manifold":
      return {
        archetype,
        inletPipes: pick([1, 2, 3, 4] as const, 1),
        outletPipes: pick([1, 2, 3, 4] as const, 3),
        handwheelSpokes: 3 + (ordinal % 6),
        bodyTopology: pick(["cross-manifold", "gate-siphon", "check-chamber", "three-way-diverter"] as const, 5),
        flangeBolts: 4 + ((ordinal * 2) % 8),
        flowMeterWindow: ordinal % 2 === 0,
        pressureReliefStack: (ordinal + 1) % 3 !== 0,
        bypassLoop: ordinal % 3 === 0,
      };
    case "banknote-bond-instrument":
      return {
        archetype,
        borderGuillocheWaves: 10 + ((ordinal * 3) % 22),
        cornerFrame: pick(["oval", "octagon", "shield", "diamond"] as const, 2),
        sealPosition: pick(["left", "right", "dual", "center"] as const, 4),
        sealSpikes: 10 + ((ordinal * 2) % 14),
        couponStubs: ordinal % 7,
        signatureLines: pick([1, 2, 3] as const, 6),
        watermarkMotif: pick(["eagle-crest", "globe-grid", "scales", "tower", "cipher"] as const, 8),
      };
    case "legal-dossier-filing": {
      const rows = 4 + (ordinal % 7);
      return {
        archetype,
        pageStackCount: pick([1, 2, 3, 4] as const, 1),
        headerStyle: pick(["sec-edgar", "irs-boxed", "congress-bill", "court-caption", "actuarial-schedule"] as const, 3),
        tableRows: rows,
        tableCols: pick([2, 3, 4, 5] as const, 5),
        redactionBars: ordinal % 5,
        highlightedRow: ordinal % rows,
        officialStamp: pick(["circular-seal", "boxed-stamp", "notary-ribbon", "none"] as const, 7),
        binderHoles: pick(["top-two", "left-three", "none"] as const, 9),
      };
    }
    case "semiconductor-die-reticle":
      return {
        archetype,
        coreGridCols: 2 + (ordinal % 7),
        coreGridRows: 2 + ((ordinal + 2) % 6),
        hbmStacks: (ordinal % 4) * 2,
        substratePinsPerSide: 6 + ((ordinal * 3) % 14),
        packageShape: pick(["square-bga", "rect-interposer", "wafer-sector", "pcie-card"] as const, 2),
        heatSpreaderNotches: 2 + (ordinal % 6),
        traceDensity: pick([1, 2, 3] as const, 5),
      };
    case "server-compute-chassis":
      return {
        archetype,
        rackUnitsU: 2 + (ordinal % 8),
        driveBaysPerRow: 3 + (ordinal % 8),
        fanRotors: pick([0, 1, 2, 3, 4] as const, 2),
        frontPanelStyle: pick(["led-matrix", "patch-cables", "liquid-manifold", "tape-reels"] as const, 4),
        exhaustVents: 4 + ((ordinal * 2) % 10),
        powerBusBars: ordinal % 2 === 0,
      };
    case "grid-power-apparatus":
      return {
        archetype,
        insulatorStacks: 2 + (ordinal % 5),
        insulatorSheds: 3 + (ordinal % 6),
        radiatorFins: 4 + ((ordinal * 2) % 10),
        trussTiers: 2 + (ordinal % 5),
        apparatusForm: pick(["transformer-tank", "lattice-pylon", "turbine-nacelle", "bess-enclosure", "breaker-bank"] as const, 3),
        coronaArcs: ordinal % 2 === 1,
      };
    case "industrial-plant-rig":
      return {
        archetype,
        chimneyCount: pick([0, 1, 2, 3, 4] as const, 1),
        gearTeeth: 8 + ((ordinal * 2) % 14),
        pistonCount: pick([1, 2, 3, 4] as const, 3),
        rigForm: pick(["rotary-kiln", "articulated-arm", "gantry-press", "distillation-tower", "bucket-wheel"] as const, 5),
        conveyorRollers: 4 + (ordinal % 7),
        hopperCone: ordinal % 2 === 0,
      };
    case "maritime-defense-vessel":
      return {
        archetype,
        hullLengthRatio: Number((0.62 + ((ordinal * 7) % 34) * 0.01).toFixed(2)),
        superstructurePos: pick(["aft", "mid", "forward", "submerged", "airframe"] as const, 2),
        cargoBaysOrCells: 3 + (ordinal % 10),
        radarMasts: pick([1, 2, 3] as const, 4),
        craftClass: pick(["container-hull", "tanker-hull", "cable-ship", "warship-vls", "submarine", "delta-uav", "missile-stage"] as const, 6),
        wakeWaves: 2 + (ordinal % 5),
      };
    case "subsea-network-node":
      return {
        archetype,
        armorWireCount: 8 + ((ordinal * 3) % 18),
        fiberPairCount: 4 + ((ordinal * 2) % 16),
        sheathLayers: pick([2, 3, 4, 5] as const, 2),
        nodeForm: pick(["radial-cross-section", "inline-repeater", "branching-y", "landing-vault", "grapnel-plow"] as const, 4),
      };
    case "architectural-elevation":
      return {
        archetype,
        stories: 1 + (ordinal % 5),
        windowCols: 2 + (ordinal % 6),
        roofProfile: pick(["pitched-gable", "classical-pediment", "sawtooth-factory", "flat-cleanroom", "mansard", "vaulted-hangar"] as const, 2),
        columnsCount: 2 + ((ordinal * 2) % 6),
        hvacUnits: ordinal % 4,
        wingExtension: ordinal % 2 === 0,
        foundationSteps: pick([1, 2, 3, 4] as const, 5),
      };
    case "consumer-exploded-bom":
      return {
        archetype,
        explodedLayers: pick([3, 4, 5, 6] as const, 1),
        layerSpreadPx: 18 + ((ordinal * 3) % 18),
        calloutSide: pick(["right", "alternating"] as const, 3),
        silhouetteItem: pick(["device-slab", "chassis-pack", "medical-scanner", "carton-crate", "garment-footwear", "vial-blister"] as const, 5),
        fastenerAxisLines: pick([2, 3, 4] as const, 7),
      };
    case "balance-ledger-contraption":
      return {
        archetype,
        beamTiltDeg: -18 + ((ordinal * 5) % 37),
        leftWeights: pick([1, 2, 3, 4, 5] as const, 1),
        rightWeights: pick([1, 2, 3, 4, 5] as const, 3),
        fulcrumStyle: pick(["knife-edge", "truss-pedestal", "hydraulic-ram", "hanging-yoke"] as const, 5),
        graduatedArcTicks: 5 + ((ordinal * 2) % 11),
        panShape: pick(["flat-tray", "suspended-dish", "hopper-bucket"] as const, 7),
      };
    case "archival-artifact-engraving":
      return {
        archetype,
        rimSerrations: 12 + ((ordinal * 4) % 28),
        artifactShape: pick(["medallion-coin", "coupon-sheet", "ingot-trapezoid", "ticker-dome", "punch-card", "wax-ribbon-seal"] as const, 2),
        engravingHatchLines: 6 + ((ordinal * 3) % 14),
        perforationCols: 2 + (ordinal % 5),
        eraYear: String(1894 + ((ordinal * 7) % 133)),
      };
    case "chart-instrument-frame": {
      const pts = 5 + (ordinal % 9);
      return {
        archetype,
        gridDivisionsX: 4 + (ordinal % 6),
        gridDivisionsY: 3 + (ordinal % 5),
        curveProfile: pick(["inversion-spread", "exponential-cliff", "step-ratchet", "dual-divergence", "pyramid-bars", "waterfall-steps"] as const, 2),
        dataPointsCount: pts,
        thresholdLinePct: Number((0.28 + ((ordinal * 9) % 58) * 0.01).toFixed(2)),
        calloutIndex: ordinal % pts,
      };
    }
    case "telestrator-annotation-rig":
      return {
        archetype,
        rigVariant: pick(["curly-brace", "vernier-caliper", "rubber-stamp", "loupe-reticle", "dimension-span", "timeline-flag", "audit-tag"] as const, 2),
        tickSubdivisions: 6 + ((ordinal * 3) % 16),
        rotationDeg: -12 + ((ordinal * 5) % 25),
        doubleBorder: ordinal % 2 === 0,
        cornerTicks: (ordinal + 1) % 2 === 0,
      };
  }
}

