const ALL_CATALOG_ROWS: readonly CatalogRow[] = ([] as CatalogRow[]).concat(
  CATALOG_ROWS,
  ROWS_ENERGY_GRID,
  ROWS_LABOR,
  ROWS_LEGAL,
  ROWS_LEGAL_AND_GEO_A,
  ROWS_GEO_B,
  ROWS_HOUSEHOLD_A,
  ROWS_HOUSE_AND_HIST_A,
  ROWS_HIST_B,
  ROWS_MARITIME_A,
  ROWS_MAR_AND_EDIT_A,
  ROWS_EDIT_B
);

const archetypeOrdinals: Record<string, number> = {};

export const DOMAIN_BLUEPRINTS: readonly ParametricPropBlueprint[] = ALL_CATALOG_ROWS.map((row) => {
  const [id, title, domain, category, ep, datumCode, primaryMetric, secondaryLabel, accentRole, archetype, extraTags] = row;
  const ord = archetypeOrdinals[archetype] ?? 0;
  archetypeOrdinals[archetype] = ord + 1;

  const kwSet: string[] = [domain, category, archetype, ep];
  for (let i = 0; i < extraTags.length; i++) {
    if (kwSet.indexOf(extraTags[i]) === -1) {
      kwSet.push(extraTags[i]);
    }
  }

  return {
    id,
    title,
    label: title,
    domain,
    category,
    episodeTags: [ep],
    keywords: kwSet,
    animatableParts: ARCHETYPE_PARTS[archetype],
    defaultMotion: ARCHETYPE_MOTIONS[archetype],
    accentRole,
    datumCode,
    primaryMetric,
    secondaryLabel,
    geometry: buildDistinctGeometry(archetype, ord, id),
  };
});

export const DOMAIN_CATALOG_ENTRIES: readonly PropVaultEntry[] = DOMAIN_BLUEPRINTS.map((bp) => ({
  id: bp.id,
  title: bp.title,
  label: bp.title,
  kind: "parametric-blueprint",
  domain: bp.domain,
  category: bp.category,
  episodeTags: bp.episodeTags,
  keywords: bp.keywords,
  animatableParts: bp.animatableParts,
  defaultMotion: bp.defaultMotion,
  aspectRatio: "4:3",
  viewBox: "0 0 400 300",
  blueprint: bp,
  Component: createParametricPropComponent(bp),
}));

const catalogMap: Record<string, PropVaultEntry> = {};
for (let i = 0; i < DOMAIN_CATALOG_ENTRIES.length; i++) {
  catalogMap[DOMAIN_CATALOG_ENTRIES[i].id] = DOMAIN_CATALOG_ENTRIES[i];
}

export const DOMAIN_CATALOG_BY_ID: Readonly<Record<string, PropVaultEntry>> = catalogMap;
